require __DIR__.'/library_network_bootstrap.php';
$db=DB();$db->db_debug=false;$out="# Baris yang ditahan untuk verifikasi — task4\n\nDihasilkan dari arsip hasil import. Baris di bawah **tidak dibuat menjadi perpustakaan baru**, agar tidak menduplikasi sekolah negeri yang mungkin salah nomor/nama. NPSN dan nama master Dapodik tidak diubah.\n\nJawaban yang diperlukan: **ID pendataan → ID master yang benar**, atau **lembaga berbeda, boleh ditambahkan**. Jika ada penggabungan/perubahan nama sekolah, sertakan keterangan. Kandidat bukan pasangan otomatis.\n\n| ID pendataan | Baris XLS asli | Perpustakaan / lembaga induk | Kecamatan sumber | Catatan |\n| --- | ---: | --- | --- | --- |\n";
$escape=function($v){return str_replace(["|","\n","\r"],['\\|',' ',' '],(string)$v);};
foreach($db->where('source_system','pendataan_task4')->where('library_id IS NULL',null,false)->order_by('source_row')->get('library_source_records')->result_array()as$r){$s=json_decode($r['source_json'],true);$out.='| '.implode(' | ',array_map($escape,[$r['source_id'],$r['source_row'],$s['Nama'].' / '.$s['Lembaga Induk'],$s['Kecamatan'],$r['note']]))." |\n";}
$out.="\n## Kelengkapan lokasi unit baru\n\n152 unit tambahan belum ditampilkan sebagai titik karena GPS kosong, tidak masuk rentang wilayah yang wajar, atau berulang massal. Koordinat sumber asli tidak hilang: tersimpan dalam arsip privat. Lengkapi GPS setelah diperiksa; jangan memakai koordinat 0,0 sebagai lokasi nyata.\n\n19 unit tambahan belum memiliki ID desa yang cocok, dan 1 di antaranya juga belum memiliki ID kecamatan. Teks wilayah sumber tetap disimpan.\n\n| ID library | ID pendataan | Nama | Kecamatan | Desa sumber |\n| ---: | --- | --- | --- | --- |\n";
foreach($db->select('id,source_id,name,district,village')->where('source_system','pendataan_task4')->where('village_id IS NULL',null,false)->order_by('name')->get('libraries')->result_array()as$r)$out.='| '.implode(' | ',array_map($escape,array_values($r)))." |\n";
file_put_contents(FCPATH.'docs/iplm/PERLU_VERIFIKASI_TASK4.md',$out);echo "Review list generated without private contacts or activation secrets.\n";
